function confidenceColor(confidence: number): string {
  if (confidence >= 0.8) return "bg-green-500";
  if (confidence >= 0.6) return "bg-emerald-500";
  if (confidence >= 0.3) return "bg-amber-500";
  return "bg-red-500";
}

export function GapCard({ gap }: GapCardProps) {
  return (
    <Card>
      <CardContent className="p-4">
        <div className="flex items-start justify-between gap-2">
          <div className="flex-1 min-w-0">
            <h3 className="text-sm font-medium leading-tight">{gap.title}</h3>
            <p className="text-xs text-muted-foreground mt-1 line-clamp-2">{gap.description}</p>
            <div className="flex items-center gap-2 mt-2">
              <Badge variant="outline" className="text-xs">
                {gap.gap_type}
              </Badge>
              {gap.potential_impact && (
                <span className="text-xs text-muted-foreground">{gap.potential_impact}</span>
              )}
            </div>
          </div>
          <div className="flex-shrink-0 flex flex-col items-center gap-1">
            <span className="text-xs text-muted-foreground">
              {(gap.confidence * 100).toFixed(0)}%
            </span>
            <div className="h-2 w-16 rounded-full bg-secondary overflow-hidden">
              <div
                className={cn("h-full rounded-full", confidenceColor(gap.confidence))}
                style={{ width: `${gap.confidence * 100}%` }}
              />
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

import { apiFetch } from "./client";
import type { IdeaListResponse, IdeaDetail, IdeaFeedbackRequest } from "./types";

export function listIdeas(params?: {
  domain?: string;
  min_score?: number;
  limit?: number;
  offset?: number;
}): Promise<IdeaListResponse> {
  const search = new URLSearchParams();
  if (params?.domain) search.set("domain", params.domain);
  if (params?.min_score !== undefined) search.set("min_score", String(params.min_score));
  if (params?.limit) search.set("limit", String(params.limit));
  if (params?.offset) search.set("offset", String(params.offset));
  const qs = search.toString();
  return apiFetch(`/ideas/${qs ? `?${qs}` : ""}`);
}

export function getIdea(id: number): Promise<{ idea: IdeaDetail }> {
  return apiFetch(`/ideas/${id}`);
}

export function submitFeedback(
  id: number,
  req: IdeaFeedbackRequest,
): Promise<{ id: number; user_rating: number; user_notes: string | null }> {
  return apiFetch(`/ideas/${id}/feedback`, {
    method: "POST",
    body: JSON.stringify(req),
  });
}

export function refineIdea(
  id: number,
): Promise<{ id: number; novelty_score: number; feasibility_score: number; proposal_title: string }> {
  return apiFetch(`/ideas/${id}/refine`, { method: "POST" });
}

